module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding: 0 = waiting for byte 1, 1 = received byte 1, waiting for byte 2,
    // 2 = received byte 2, waiting for byte 3
    reg [1:0] state;
    reg [1:0] next_state;

    // Byte shift register: holds the last three received bytes
    reg [7:0] byte1;
    reg [7:0] byte2;
    reg [7:0] byte3;

    // Combinational next-state logic
    always @(*) begin
        case (state)
            2'b00: begin
                // Waiting for a byte with bit 3 set (in[3] == 1)
                if (in[3]) begin
                    next_state = 2'b01;
                end else begin
                    next_state = 2'b00;
                end
            end
            2'b01: begin
                // Received byte 1, now waiting for byte 2
                next_state = 2'b10;
            end
            2'b10: begin
                // Received byte 2, now waiting for byte 3
                next_state = 2'b11;
            end
            2'b11: begin
                // Received byte 3, message complete; next cycle go back to waiting
                next_state = 2'b00;
            end
            default: next_state = 2'b00;
        endcase
    end

    // Sequential state update (positive edge of clock, active-high synchronous reset)
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end

    // Sequential datapath: shift bytes on every clock edge when not in reset
    // We update the shift register regardless of state so that the three most
    // recent bytes are always available when done is asserted.
    always @(posedge clk) begin
        if (reset) begin
            byte1 <= 8'b0;
            byte2 <= 8'b0;
            byte3 <= 8'b0;
        end else begin
            byte1 <= in;
            byte2 <= byte1;
            byte3 <= byte2;
        end
    end

    // Output logic: assert done in the cycle immediately after the third byte
    // of a message was successfully received.
    // The third byte is byte3; done is high when we transition into state 2'b00
    // from state 2'b11 (i.e., we just finished receiving the third byte).
    always @(posedge clk) begin
        if (reset) begin
            done <= 1'b0;
            out_bytes <= 24'b0;
        end else begin
            // default: keep previous values
            // done is pulsed high for one cycle after receiving the third byte
            if (state == 2'b11) begin
                // We have just received the third byte; assert done this cycle
                done <= 1'b1;
                // output the 24‑bit message: byte1 is the first byte,
                // byte2 is the second, byte3 is the third
                out_bytes <= {byte1, byte2, byte3};
            end else begin
                done <= 1'b0;
            end
        end
    end

endmodule

