module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // One-hot encoded state bits (active high)
    // S, S1, S11, S110, B0, B1, B2, B3, Count, Wait
    wire s       = state[0];
    wire s1      = state[1];
    wire s11     = state[2];
    wire s110    = state[3];
    wire b0      = state[4];
    wire b1      = state[5];
    wire b2      = state[6];
    wire b3      = state[7];
    wire count   = state[8];
    wire wait_n  = state[9];

    // ---------- Next-state signals (one-hot) ----------
    wire next_s;
    wire next_s1;
    wire next_s11;
    wire next_s110;
    wire next_b0;
    wire next_b1;
    wire next_b2;
    wire next_b3;
    wire next_count;
    wire next_wait;

    // ---------- State transition logic (combinational) ----------
    // S next-state
    assign next_s = (!d & s) | (!d & s110);

    // S1 next-state
    assign next_s1 = (d & s) | (!d & s11);

    // S11 next-state
    assign next_s11 = (d & s1) | (!d & s11);

    // S110 next-state
    assign next_s110 = (!d & s110) | (d & b0);  // d=0->S, d=1->B0 (but B0 is not directly next; B0 goes to B1 next cycle. Here we map d=1 from S110 to B0 next-state)

    // B0 next-state (always goes to B1)
    assign next_b0 = 1'b0;  // B0 never stays; next is B1

    // B1 next-state (always goes to B2)
    assign next_b1 = 1'b0;  // B1 never stays; next is B2

    // B2 next-state (always goes to B3)
    assign next_b2 = 1'b0;  // B2 never stays; next is B3

    // B3 next-state (always goes to Count)
    assign next_b3 = 1'b0;  // B3 never stays; next is Count

    // Count next-state
    assign next_count = (done_counting == 1'b0) ? count : 1'b0;

    // Wait next-state
    assign next_wait = (done_counting == 1'b1) ? 1'b1 : 1'b0;

    // ---------- One-hot priority encoding for next state ----------
    // Build next-state one-hot vector
    wire [9:0] next_state;
    assign next_state = {next_s, next_s1, next_s11, next_s110,
                         next_b0, next_b1, next_b2, next_b3,
                         next_count, next_wait};

    // ---------- Output one-hot assertion signals ----------
    // B3_next: assert when next-state is B3
    assign B3_next = next_state[7];

    // S_next: assert when next-state is S
    assign S_next  = next_state[0];

    // S1_next: assert when next-state is S1
    assign S1_next = next_state[1];

    // Count_next: assert when next-state is Count
    assign Count_next = next_state[8];

    // Wait_next: assert when next-state is Wait
    assign Wait_next = next_state[9];

    // ---------- Output logic (Moore) ----------
    // shift_ena: asserted in B0, B1, B2, B3
    assign shift_ena = b0 | b1 | b2 | b3;

    // counting: asserted in Count state
    assign counting = count;

    // done: asserted in Wait state (done=1) and also when transitioning from Wait to S? 
    // Specification: Wait (done=1) -- ack=1 --> S. done output is 1 in Wait state.
    // Also done is listed as output; assume done=1 when in Wait state.
    assign done = wait_n;

endmodule

