module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    wire d0, q0, d1, q1, d2, q2;

    // XOR gate: first input is x, second input is q0 (feedback from FF0)
    assign d0 = x ^ q0;

    // AND gate: first input is x, second input is ~q1 (complemented output of FF1)
    assign d1 = x & ~q1;

    // OR gate: first input is x, second input is ~q2 (complemented output of FF2)
    assign d2 = x | ~q2;

    // D flip-flops (positive edge-triggered, asynchronous reset to 0)
    // Rule 1: LSB carry-in of ripple-carry adders is tied to 0 – not applicable here,
    // but we explicitly initialize q0, q1, q2 to 0 at reset.
    dff_rst ff0 (.clk(clk),  .d(d0),  .q(q0),  .rst(1'b1));
    dff_rst ff1 (.clk(clk),  .d(d1),  .q(q1),  .rst(1'b1));
    dff_rst ff2 (.clk(clk),  .d(d2),  .q(q2),  .rst(1'b1));

    // Three-input NOR gate: inputs are q0, q1, q2
    // NOR is active-low; output is 1 only when all inputs are 0.
    assign z = ~(q0 | q1 | q2);

endmodule

