module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    //----------------------------------------------------------------
    // FSM state encoding (2 bits)
    //----------------------------------------------------------------
    typedef enum logic [1:0] {
        STATE_A   = 2'b00,  // beginning state (reset asserted or initial)
        STATE_B   = 2'b01,  // f = 1 for one cycle, waiting for x sequence
        STATE_C   = 2'b10,  // x sequence 1,0,1 detected, g = 1 for one cycle
        STATE_D   = 2'b11   // g = 1 permanently waiting for y within 2 cycles
    } state_t;

    state_t   state, nxt_state;
    logic     f_fall, g_fall;   // registered outputs for one-cycle pulses
    logic [1:0] x_seq;          // shift register for x history (x2, x1, x0)
    logic [1:0] y_cnt;          // counter for y detection window (1, 0)

    //----------------------------------------------------------------
    // Output assignments
    //----------------------------------------------------------------
    // f is 1 for exactly one clock cycle after reset de-assertion.
    // We generate a one-cycle pulse by XORing registered and new state.
    assign f = (state == STATE_B) ? 1'b1 : 1'b0;

    // g is 1 when we are in STATE_C (just detected) or STATE_D (maintained).
    // It also pulses high for one cycle when entering STATE_C.
    assign g = (state == STATE_C) | (state == STATE_D);

    //----------------------------------------------------------------
    // State register (positive-edge triggered, synchronous active-low reset)
    //----------------------------------------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state      <= STATE_A;
            x_seq      <= 3'b0;   // enough bits to hold 1,0,1 pattern
            y_cnt      <= 2'b0;
        end else begin
            state      <= nxt_state;
            // shift x history: new x comes in at bit 0, old bits shift right
            x_seq      <= {x_seq[1:0], x};
            // y counter: increment if g was 1 last cycle and y was 1,
            // else reset to 0 if y was 0, else cap at 2'b11
            if (y) begin
                if (y_cnt < 2'b11)
                    y_cnt <= y_cnt + 1'b1;
            end else begin
                y_cnt <= 2'b0;
            end
        end
    end

    //----------------------------------------------------------------
    // Next‑state logic (combinational)
    //----------------------------------------------------------------
    always_comb begin
        // default next state is current state
        nxt_state = state;

        case (state)
            STATE_A: begin
                // After reset de‑assertion, go to STATE_B and assert f for one cycle.
                nxt_state = STATE_B;
            end

            STATE_B: begin
                // Monitor x for pattern 1,0,1.
                // Pattern detected when x_seq == 3'b101 (x2=1, x1=0, x0=1)
                if (x_seq == 3'b101) begin
                    nxt_state = STATE_C;   // enter STATE_C, g will pulse high
                end else begin
                    nxt_state = STATE_B;   // keep monitoring
                end
            end

            STATE_C: begin
                // g has pulsed high for one cycle. Now start monitoring y.
                // If y becomes 1 within two cycles -> STATE_D (g stays 1).
                // If two cycles pass without y=1 -> go to STATE_A (g=0 permanently).
                if (y_cnt == 2'b11) begin   // y was 1 in both of the last two cycles
                    nxt_state = STATE_D;
                end else if (y_cnt == 2'b10) begin // y was 1 last cycle, but not this one yet
                    // We need to check the next cycle; if y is 1 now we go to D,
                    // otherwise after this cycle we will have counted two zeros.
                    // To keep the logic simple we stay in C and let the counter
                    // continue; the counter will reach 2'b11 only if y stays 1,
                    // otherwise it will reset.
                    nxt_state = STATE_C;
                end else begin
                    // y_cnt is 2'b00 or 2'b01, meaning we have not seen y=1 yet
                    // or only once. Stay in C and keep counting.
                    nxt_state = STATE_C;
                end
            end

            STATE_D: begin
                // g = 1 permanently. If y never became 1 within two cycles
                // we would have left earlier; here we just stay as long as
                // reset is not asserted. If reset asserts we go to A.
                // No transition out of D except reset.
                nxt_state = STATE_D;
            end

            default: nxt_state = STATE_A;
        endcase
    end

    //----------------------------------------------------------------
    // One‑cycle pulse registers for f and g (optional, for clean output)
    //----------------------------------------------------------------
    // f is already a one‑cycle pulse because it is high exactly in STATE_B.
    // g is high in STATE_C and STATE_D; the pulse in STATE_C is naturally
    // one cycle because the FSM transitions out of STATE_C on the next edge.
    // No extra registers are needed.

endmodule

