module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 0=S0, 1=S1, 2=S2, 3=S3
    reg [1:0] state;
    reg [3:0] shift_reg; // Holds the last 4 bits for sequence detection

    // State transition logic (positive edge triggered, synchronous reset)
    always @(posedge clk) begin
        if (reset) begin
            state     <= 2'b00;
            shift_reg <= 4'b0000;
        end else begin
            // Shift the input bit into the right side of the register
            shift_reg <= {shift_reg[2:0], data};

            // Detect sequence 1101: pattern 1,1,0,1
            // shift_reg bits: [3] [2] [1] [0] (newest to oldest)
            // Sequence found when: bit3=1, bit2=1, bit1=0, bit0=1
            if (shift_reg == 4'b1101) begin
                state <= 2'b11; // Enter "found" state
            end else begin
                // Advance through the sequence states
                case (state)
                    2'b00: if (data == 1'b1) state <= 2'b01; // S0 -> S1
                    2'b01: if (data == 1'b1) state <= 2'b10; // S1 -> S2
                    2'b10: if (data == 1'b0) state <= 2'b11; // S2 -> S3
                    default: state <= 2'b00;                   // S3 -> S0 (reset on mismatch)
                endcase
            end
        end
    end

    // Output logic: start_shifting is 1 once the sequence is found, forever until reset
    assign start_shifting = (state == 2'b11);

endmodule

