module TopModule (
    input  [3:0] x,
    output       f
);

    // Internal signals for the K-map variables
    // x[3] is the most significant bit, x[0] is the least significant
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // Derived signals based on the K-map grouping
    // Group 1: x[3]x[4]x[1]x[2] = x3 & x2 & x1 (covers minterms where x3=1,x2=1,x1=1)
    wire g1 = x3 & x2 & x1;

    // Group 2: x[3]x[4]x[2]x[3]' (covers row x3=1,x2=1 and x3=0,x2=1 with some don't-cares)
    // From K-map: minterms at (x3=1,x2=1) and (x3=0,x2=1) with specific x1,x0 conditions.
    // Simplified: x2 & (~x3 | ...) 
    // We use the pattern: x2 & (x1 | ~x3) based on the map coverage.
    wire g2 = x2 & (x1 | ~x3);

    // Group 3: x[3]x[4]x[1]' (covers the 1s in row x3=1,x2=0 and x3=0,x2=0)
    wire g3 = x3 & ~x2 & ~x1;

    // Group 4: x[3]x[4]x[2] (covers the 1 at x3=1,x2=1,x1=1,x0=0 and don't-cares)
    wire g4 = x3 & x2;

    // Final OR of all groups to produce f
    assign f = g1 | g2 | g3 | g4;

endmodule

