    reg  [3:0] ones;      // q[3:0]
    reg  [3:0] tens;      // q[7:4]
    reg  [3:0] hundreds;  // q[11:8]
    reg  [3:0] thousands; // q[15:12]

    // Internal carry signals for the BCD increment chain
    wire ones_carry;
    wire tens_carry;
    wire hundreds_carry;

    // ---- BCD increment logic for the ones digit ----
    // ones increments every clock. If current value is 9, next is 0 and carry=1.
    assign ones_carry = (ones == 4'b1001);
    assign ones_next  = (ones == 4'b1001) ? 4'b0 : ones + 1'b1;

    // ---- BCD increment logic for the tens digit ----
    // tens increments only when ones_carry is high.
    assign tens_carry = (tens == 4'b1001) & ones_carry;
    assign tens_next  = (tens == 4'b1001) ? (ones_carry ? 4'b0 : 4'b1001) : (ones_carry ? tens + 1'b1 : tens);

    // ---- BCD increment logic for the hundreds digit ----
    // hundreds increments only when tens_carry is high.
    assign hundreds_carry = (hundreds == 4'b1001) & tens_carry;
    assign hundreds_next  = (hundreds == 4'b1001) ? (tens_carry ? 4'b0 : 4'b1001) : (tens_carry ? hundreds + 1'b1 : hundreds);

    // ---- BCD increment logic for the thousands digit (MSB) ----
    // thousands increments only when hundreds_carry is high.
    // If it overflows (was 9 and gets carry), it wraps to 0.
    assign thousands_carry = (thousands == 4'b1001) & hundreds_carry;
    assign thousands_next  = (thousands == 4'b1001) ? (hundreds_carry ? 4'b0 : 4'b1001) : (hundreds_carry ? thousands + 1'b1 : thousands);

    // ---- ena outputs ----
    // ena[0] corresponds to tens enable (carry from ones)
    // ena[1] corresponds to hundreds enable (carry from tens)
    // ena[2] corresponds to thousands enable (carry from hundreds)
    assign ena[0] = ones_carry;
    assign ena[1] = tens_carry;
    assign ena[2] = hundreds_carry;

    // ---- Sequential logic (positive edge triggered) ----
    always @(posedge clk) begin
        if (reset) begin
            // Synchronous active-high reset
            ones    <= 4'b0;
            tens    <= 4'b0;
            hundreds<= 4'b0;
            thousands<= 4'b0;
        end else begin
            ones    <= ones_next;
            tens    <= tens_next;
            hundreds<= hundreds_next;
            thousands<= thousands_next;
        end
    end

    // ---- Output assignment for q ----
    // q[3:0] = ones, q[7:4] = tens, q[11:8] = hundreds, q[15:12] = thousands
    assign q = {thousands, hundreds, tens, ones};

endmodule

