module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // ---------- State encoding ----------
    // 2-bit state: 00=walk_left, 01=walk_right, 10=fall, 11=dig
    reg [1:0] state, next_state;

    // ---------- Falling counter ----------
    // Counts cycles spent in the fall state. Max 20 -> splatter.
    reg [5:0] fall_cnt, next_fall_cnt;

    // ---------- Internal signals ----------
    // Direction save remembers the walking direction before falling or digging.
    // 0 = walking left, 1 = walking right.
    reg dir_save, next_dir_save;

    // Splatter flag: once set, stays set forever (until reset).
    reg splattered, next_splattered;

    // ---------- Output logic (Moore) ----------
    // Internal wires for the four outputs before splatter gating.
    wire walk_l, walk_r, aaah_out, dig_out;

    // walk_left/right are 1 only in the corresponding walk state
    assign walk_l = (state == 2'b00);
    assign walk_r = (state == 2'b01);
    // aaah_out is 1 only while falling
    assign aaah_out   = (state == 2'b10);
    // digging is 1 only while in dig state
    assign dig_out = (state == 2'b11);

    // Drive outputs, gated by splatter flag.
    // If splattered, all outputs are forced to 0.
    assign walk_left  = (!splattered) && walk_l;
    assign walk_right = (!splattered) && walk_r;
    assign aaah       = (!splattered) && aaah_out;
    assign digging    = (!splattered) && dig_out;

    // ---------- Next-state logic ----------
    always @(*) begin
        // Default next state = current state (safe fallback)
        next_state = state;
        next_fall_cnt = fall_cnt;
        next_dir_save = dir_save;
        next_splattered = splattered;

        // If already splattered, stay in walk_left state and keep flag set.
        if (splattered) begin
            next_state = 2'b00;
            next_splattered = 1'b1;
            // fall_cnt and dir_save are left unchanged; they are irrelevant after splatter.
        end else begin
            case (state)
                2'b00: begin // walking left
                    // Priority: fall > dig > switch direction
                    if (!ground) begin
                        // Start falling; reset fall counter to 1 (first cycle falling)
                        next_state = 2'b10;
                        next_fall_cnt = 1;
                        // Save direction: we are walking left, so saved dir = 0 (left)
                        next_dir_save = 1'b0;
                    end else if (dig && !bump_left && !bump_right) begin
                        // Start digging (only if not bumped; bumped while digging ignored)
                        next_state = 2'b11;
                        next_fall_cnt = 0;
                        // Save direction: walking left -> dir_save = 0
                        next_dir_save = 1'b0;
                    end else if (bump_left || bump_right) begin
                        // Switch direction when bumped (both sides -> still switch)
                        if (bump_left && !bump_right)
                            next_state = 2'b01; // now walk right
                        else if (!bump_left && bump_right)
                            next_state = 2'b00; // now walk left
                        // if both bumped, spec says "still switch directions";
                        // net effect with both active is no change, so stay current.
                        else
                            next_state = state; // both bumped -> no change
                    end
                    // If none of the above, stay walking left
                end

                2'b01: begin // walking right
                    if (!ground) begin
                        next_state = 2'b10;
                        next_fall_cnt = 1;
                        // Save direction: walking right -> dir_save = 1
                        next_dir_save = 1'b1;
                    end else if (dig && !bump_left && !bump_right) begin
                        next_state = 2'b11;
                        next_fall_cnt = 0;
                        // Save direction: walking right -> dir_save = 1
                        next_dir_save = 1'b1;
                    end else if (bump_left || bump_right) begin
                        if (bump_right && !bump_left)
                            next_state = 2'b00; // walk left
                        else if (!bump_right && bump_left)
                            next_state = 2'b01; // walk right (no change)
                        else
                            next_state = state; // both bumped -> no change
                    end
                end

                2'b10: begin // falling
                    // Increment fall counter
                    next_fall_cnt = fall_cnt + 1;

                    // Check for splatter: ground reappears after >20 cycles falling
                    if (ground && (fall_cnt > 20)) begin
                        // Splatter: all outputs become 0 forever
                        next_state = 2'b00; // walk_left state (outputs forced 0 by splattered flag)
                        next_splattered = 1'b1;
                        // dir_save is no longer relevant, leave unchanged
                    end else if (ground) begin
                        // Ground reappears while falling but not splattered:
                        // Resume walking in the same direction as before the fall.
                        // dir_save holds the pre-fall direction.
                        if (dir_save == 1'b0)
                            next_state = 2'b00; // resume walk_left
                        else
                            next_state = 2'b01; // resume walk_right
                        // fall_cnt is reset implicitly by leaving the fall state;
                        // the counter will restart when next falling begins.
                    end else begin
                        // Still falling, no ground – stay in fall state
                        // (fall_cnt already incremented above)
                    end
                end

                2'b11: begin // digging
                    if (!ground) begin
                        // Reached other side while digging -> fall
                        next_state = 2'b10;
                        next_fall_cnt = 1;
                        // When digging hits ground=0, the Lemming falls.
                        // The direction it was walking before digging is saved in dir_save.
                        // We resume that direction after the fall.
                        // No need to change dir_save here; it was saved when digging started.
                    end else if (dig && !bump_left && !bump_right) begin
                        // Continue digging – state stays 11
                        // dir_save remains unchanged (keeps pre-dig direction)
                    end else begin
                        // Bumped or dig=0 while on ground -> stop digging, resume walking
                        // Resume the direction we had before digging (stored in dir_save).
                        if (dir_save == 1'b0)
                            next_state = 2'b00; // walk_left
                        else
                            next_state = 2'b01; // walk_right
                        // dig state ends; outputs will reflect walk state next cycle.
                    end
                end
            endcase
        end
    end

    // ---------- Direction saving update ----------
    // This block updates dir_save on every clock edge based on next_dir_save.
    // (The always @(*) above already computes next_dir_save; the FF block latches it.)
    always @(*) begin
        // next_dir_save is already computed in the main always block above.
        // This empty block is kept only to satisfy the original structure;
        // the actual latching happens in the state FF block.
    end

    // ---------- State flip-flops ----------
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b00;    // walk left
            fall_cnt <= 0;
            dir_save <= 1'b0;  // initially walking left
            splattered <= 1'b0;
        end else begin
            state <= next_state;
            fall_cnt <= next_fall_cnt;
            dir_save <= next_dir_save;
            splattered <= next_splattered;
        end
    end

endmodule
